mapper.update:
UPDATE makeover_task
SET status = 1, started_at = #{startedAt}
WHERE id = #{id}

UPDATE makeover_task
SET status = 2, finished_at = #{finishedAt}
WHERE id = #{id}

UPDATE makeover_task
SET status = 3, error_message = #{errorMessage}, finished_at = #{finishedAt}
WHERE id = #{id}

UPDATE makeover_task
SET retry_count = retry_count + 1
WHERE id = #{id}
